import re
def pipeline(steps):
    def decorate(function):
        def wrapper(value):
            for step in steps:
                value = step(value)
            return function(value)
        return wrapper
    return decorate
def slugify(value):
    return re.sub(r'[^a-z0-9]+', '-', value).strip('-')
@pipeline([str.strip, str.lower, slugify])
def show_slug(value):
    return value
print(show_slug(input()))

